class Solution:
    def subStrHash(self, s: str, power: int, modulo: int, k: int, hashValue: int) -> str:
        pw = [1] * k
        for i in range(1, k):
            pw[i] = pw[i - 1] * power % modulo
        for i in range(len(s) - k + 1):
            h = 0
            for j in range(k):
                h = (h + (ord(s[i + j]) - 96) * pw[j]) % modulo
            if h == hashValue:
                return s[i:i + k]
        return ''

