        int n = s.size();
        long long m = modulo, p = power;
        vector<long long> pw(k, 1);
        for (int i = 1; i < k; ++i) pw[i] = pw[i - 1] * p % m;
        for (int i = 0; i + k <= n; ++i) {
            long long h = 0;
            for (int j = 0; j < k; ++j)
                h = (h + (long long)(s[i + j] - 'a' + 1) * pw[j]) % m;
            if (h == hashValue) return s.substr(i, k);
        }
        return "";
    }
};

