class Solution:
    def subStrHash(self, s: str, power: int, modulo: int, k: int, hashValue: int) -> str:
        n = len(s)
        val = lambda c: ord(c) - 96
        pk = pow(power, k - 1, modulo)
        h = 0
        for j in range(n - 1, n - k - 1, -1):
            h = (h * power + val(s[j])) % modulo
        best = n - k
        for i in range(n - k, -1, -1):
            if h == hashValue:
                best = i
            if i:
                h = ((h - val(s[i + k - 1]) * pk) % modulo * power + val(s[i - 1])) % modulo
        return s[best:best + k]

