        int n = s.size();
        long long p = power, m = modulo, pk = 1;
        for (int i = 0; i < k - 1; ++i) pk = pk * p % m;
        auto val = [&](char c) { return (long long)(c - 'a' + 1); };
        long long h = 0;
        for (int j = n - 1; j >= n - k; --j) h = (h * p + val(s[j])) % m;
        int best = n - k;
        for (int i = n - k; i >= 0; --i) {
            if (h == hashValue) best = i;
            if (i) h = (((h - val(s[i + k - 1]) * pk) % m + m) % m * p + val(s[i - 1])) % m;
        }
        return s.substr(best, k);
    }
};

