        long p = power, m = modulo;
        long pk = 1;
        for (int i = 0; i < k - 1; i++) pk = pk * p % m;
        long h = 0;
        for (int j = n - 1; j >= n - k; j--) h = (h * p + (s.charAt(j) - 'a' + 1)) % m;
        int best = n - k;
        for (int i = n - k; i >= 0; i--) {
            if (h == hashValue) best = i;
            if (i > 0)
                h = (((h - (long)(s.charAt(i + k - 1) - 'a' + 1) * pk) % m + m) % m * p + (s.charAt(i - 1) - 'a' + 1)) % m;
        }
        return s.substring(best, best + k);
    }
};

