var subStrHash = function(s, power, modulo, k, hashValue) {
    const P = BigInt(power), M = BigInt(modulo);
    const val = c => BigInt(c.charCodeAt(0) - 96);
    const n = s.length;
    let pk = 1n;
    for (let i = 0; i < k - 1; i++) pk = pk * P % M;
    let h = 0n;
    for (let j = n - 1; j >= n - k; j--) h = (h * P + val(s[j])) % M;
    let best = n - k;
    for (let i = n - k; i >= 0; i--) {
        if (h === BigInt(hashValue)) best = i;
        if (i > 0)
            h = (((h - val(s[i + k - 1]) * pk) % M + M) % M * P + val(s[i - 1])) % M;
    }
    return s.substring(best, best + k);
};
